import json
from pathlib import Path

# ১) বাস্তব MovieLens 28 জন Warm ইউজারের পরিকল্পিত সুপারিশ স্লট গণনা (বাস্তব ক্লিক/ইম্প্রেশন নয়!)
lab = json.loads(
    Path("assets/datasets/movielens/recommendation_evaluation_lab.json").read_text(encoding="utf-8")
)

warm_rows = []
for r in lab["rows"]:
    if r["train_count"] > 0 and len(r["eligible"]) > 0:
        warm_rows.append(r)

assert len(warm_rows) == 28

def audit_planned_slots(rows_subset, policy_name):
    counts = {}
    total_slots = 0
    for r in rows_subset:
        for item in r["rankings"][policy_name]:
            counts[item] = counts.get(item, 0) + 1
            total_slots += 1
    freq_desc = sorted(counts.values(), reverse=True)
    top5_slots = 0
    for idx in range(min(5, len(freq_desc))):
        top5_slots += freq_desc[idx]
    return total_slots, len(counts), (100.0 * top5_slots / float(total_slots))

for name in ["user_cf", "mmr1", "mmr0.75", "mmr0.5"]:
    slots, distinct_n, top5_pct = audit_planned_slots(warm_rows, name)
    assert slots == 28 * 10
    print(
        f"{name:8s} -> planned_slots={slots} | distinct_items={distinct_n:3d} | top5_item_share={top5_pct:.2f}%"
    )
